#define AVSBUS_CONTROLLER__AVS_CFG_0__MAX_RETRIES_bp 16
#define AVSBUS_CONTROLLER__AVS_CFG_0__MAX_RETRIES_bw 8
#define AVSBUS_CONTROLLER__AVS_CFG_0__MAX_RETRIES_reset 0x5
